-- Polestar.ItemDB: stats of every equippable Classic Era item, from the
-- load-on-demand data addon Polestar_ItemDB (generated by
-- `node tools/polestar.js itemdb build`). The data addon calls Register once;
-- entries stay compact strings and are parsed on first lookup.
--
--   ItemDB.Load() -> loaded            -- loads Polestar_ItemDB once (C_AddOns.LoadAddOn)
--   ItemDB.IsLoaded() -> bool
--   ItemDB.Get(itemID) -> record | nil
--     record = { id, inv, ilvl, req, quality, class, subclass, allow (class mask, 0 = any),
--                unique, stats = { str = 5, armor = 92, dps = 17.8, ... } }
--   ItemDB.Meta() -> { schema, build, count } | nil
--
-- Forever.lua (generated by `node tools/polestar.js gear build` from
-- ForeverLevelingBiS, MIT) loads after Items.lua: it overlays Forever's own
-- stats (Register(nil, items)) and registers where leveling gear comes from:
--   ItemDB.LevelingMeta() -> { source, version, generated, items, quests } | nil
--   ItemDB.ItemName(id) -> name | nil
--   ItemDB.Sources(id) -> { source, ... } | nil, each one of
--       { kind = "quest", quest, name, level, req, side, zone, zoneName, dungeon }
--       { kind = "drop", npc (0 = trash), npcName, pct, zone, zoneName }
--       { kind = "craft", spell, profession, skill }
--   ItemDB.Quest(questID) -> { id, name, level, req, side (1 A, 2 H, 3 both), zone, zoneName,
--       reqRace, reqClass, dungeon, choices = { itemID... }, items = { itemID... } } | nil
--
-- Entry format: "<inv> <ilvl> <req> <quality> <classID> <subclassID>
-- [<stat><n> ...] [dmin<n> dmax<n> speed<ms>] [cls<mask>] [uniq1]"; the
-- tokens mpr/hpr stand for mp5/hp5 (stored tokens are letters then digits).
-- Weapon damage is summed over its schools; stats.dps is derived from it.

local ADDON, ns = ...

local DB = {}
ns.ItemDB = DB

local DATA_ADDON = "Polestar_ItemDB"

local type, tonumber, pcall, pairs = type, tonumber, pcall, pairs
local floor = math.floor

local raw, meta
local parsed = {} -- id -> record | false
local tried = false

local UNTOKEN = { mpr = "mp5", hpr = "hp5" }

function DB.Register(m, items)
	if type(items) ~= "table" then return end
	if raw then
		for id, s in pairs(items) do raw[id] = s end
	else
		raw = items
	end
	meta = type(m) == "table" and m or meta
	for id in pairs(parsed) do parsed[id] = nil end
	if ns.Fire then ns.Fire("ITEMDB_LOADED", meta) end
end

function DB.IsLoaded()
	return raw ~= nil
end

function DB.Meta()
	return meta
end

-- Loads the data addon the first time it is asked for, never in combat (a
-- 400 KiB parse would hitch; the next lookup out of combat loads it). A failed
-- or missing data addon is not retried this session; lookups then return nil
-- and Gear falls back to the client's own item stats.
function DB.Load()
	if raw then return true end
	if tried then return false end
	if InCombatLockdown and InCombatLockdown() then return false end
	tried = true
	local load = C_AddOns and C_AddOns.LoadAddOn
	if load then pcall(load, DATA_ADDON) end
	return raw ~= nil
end

local function parse(id, s)
	local inv, ilvl, req, quality, class, sub = s:match("^(%d+) (%d+) (%d+) (%d+) (%d+) (%d+)")
	if not inv then return false end
	local rec = {
		id = id,
		inv = tonumber(inv), ilvl = tonumber(ilvl), req = tonumber(req), quality = tonumber(quality),
		class = tonumber(class), subclass = tonumber(sub),
		allow = 0, unique = false,
		stats = {},
	}
	local dmin, dmax, speed
	-- Header fields are digits only, so they never match a token.
	for key, n in s:gmatch("(%a+)(%-?%d+)") do
		n = tonumber(n)
		if key == "dmin" then dmin = n
		elseif key == "dmax" then dmax = n
		elseif key == "speed" then speed = n
		elseif key == "cls" then rec.allow = n
		elseif key == "uniq" then rec.unique = n == 1
		else rec.stats[UNTOKEN[key] or key] = n end
	end
	if dmin and dmax and speed and speed > 0 then
		rec.speed = speed
		rec.stats.dps = floor((dmin + dmax) / 2 / (speed / 1000) * 10 + 0.5) / 10
	end
	return rec
end

function DB.Get(id)
	id = tonumber(id)
	if not id then return nil end
	if not raw then
		DB.Load()
		if not raw then return nil end
	end
	local rec = parsed[id]
	if rec == nil then
		local s = raw[id]
		rec = type(s) == "string" and parse(id, s) or false
		parsed[id] = rec
	end
	return rec or nil
end

---------------------------------------------------------------------------
-- Leveling sources (Forever.lua)
---------------------------------------------------------------------------

local lev, levMeta
local srcCache, questCache = {}, {}

function DB.RegisterLeveling(m, data)
	if type(data) ~= "table" then return end
	lev, levMeta = data, type(m) == "table" and m or nil
	srcCache, questCache = {}, {}
	if ns.Fire then ns.Fire("ITEMDB_LOADED", meta) end
end

-- Parsed quests and sources hold translated names: parse them again once
-- the names pack arrives late, and the sources when an NPC's name is learned.
ns.On("NAMES_LOADED", function() srcCache, questCache = {}, {} end)
ns.On("NAME_LEARNED", function(kind) if kind == "npc" then srcCache = {} end end)

local function leveling()
	if not lev then DB.Load() end
	return lev
end

function DB.LevelingMeta()
	leveling()
	return levMeta
end

-- Names below are the client's language's (Polestar.Names) where it has
-- them, the leveling data's English otherwise.
function DB.ItemName(id)
	id = tonumber(id)
	local d = leveling()
	return ns.Names.Item(id) or (d and d.names and d.names[id]) or nil
end

-- Zones are AreaTable areas.
local function zoneName(d, zone)
	if not zone or zone == 0 then return nil end
	return ns.Names.Area(zone) or (d.zones and d.zones[zone]) or nil
end

local function parseQuest(d, id, s)
	local head, choices, items, name = s:match("^([^|]*)|([^|]*)|([^|]*)|(.*)$")
	if not head then return false end
	local level, req, side, zone, race, class, dungeon = head:match("^(%d+) (%d+) (%d+) (%d+) (%d+) (%d+) (%d+)$")
	if not level then return false end
	local q = {
		id = id, name = ns.Names.Quest(id) or (name ~= "" and name or nil),
		level = tonumber(level), req = tonumber(req), side = tonumber(side), zone = tonumber(zone),
		reqRace = tonumber(race), reqClass = tonumber(class), dungeon = dungeon == "1",
		choices = {}, items = {},
	}
	q.zoneName = zoneName(d, q.zone)
	for n in choices:gmatch("%d+") do q.choices[#q.choices + 1] = tonumber(n) end
	for n in items:gmatch("%d+") do q.items[#q.items + 1] = tonumber(n) end
	return q
end

function DB.Quest(id)
	id = tonumber(id)
	local d = leveling()
	if not (id and d and d.quests) then return nil end
	local q = questCache[id]
	if q == nil then
		local s = d.quests[id]
		q = type(s) == "string" and parseQuest(d, id, s) or false
		questCache[id] = q
	end
	return q or nil
end

function DB.Sources(id)
	id = tonumber(id)
	local d = leveling()
	if not (id and d and d.src) then return nil end
	local list = srcCache[id]
	if list == nil then
		local s = d.src[id]
		list = false
		if type(s) == "string" then
			list = {}
			for tok in s:gmatch("%S+") do
				local q = tok:match("^q(%d+)$")
				if q then
					q = tonumber(q)
					local info = DB.Quest(q)
					list[#list + 1] = {
						kind = "quest", quest = q, name = info and info.name, level = info and info.level, req = info and info.req,
						side = info and info.side, zone = info and info.zone, zoneName = info and info.zoneName, dungeon = info and info.dungeon,
					}
				else
					local npc, pct, zone = tok:match("^d(%d+)x(%d+)z(%d+)$")
					if npc then
						npc, zone = tonumber(npc), tonumber(zone)
						list[#list + 1] = { kind = "drop", npc = npc, npcName = ns.Names.Npc(npc) or (d.npcs and d.npcs[npc]), pct = tonumber(pct) / 10, zone = zone, zoneName = zoneName(d, zone) }
					else
						local spell, prof, skill = tok:match("^c(%d+)p(%d+)s(%d+)$")
						if spell then
							list[#list + 1] = { kind = "craft", spell = tonumber(spell), profession = d.professions and d.professions[tonumber(prof)], skill = tonumber(skill) }
						end
					end
				end
			end
		end
		srcCache[id] = list
	end
	return list or nil
end
